  customers: ai_customers.data || [],
  customer: Number(appsmith.store.aiCustomer) || 0,
  facts: appsmith.store.aiFacts || {},
  messages: appsmith.store.aiMessages || [],
  busy: appsmith.store.aiBusy || '',
