}) }}

srcDoc.css:
*{box-sizing:border-box}
html,body{margin:0;overflow:hidden}
#root{height:700px}
html,body,#root{margin:0;background:#0d1822;color:#e7eef4;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;font-size:14px}
button{font:inherit;color:inherit;cursor:pointer;background:none;border:0}
.app{display:flex;flex-direction:column;height:100%}
.top{position:relative;z-index:5;flex:none;display:flex;align-items:center;gap:12px;padding:10px 18px;border-bottom:1px solid #1a2c3d}
.title{font-size:16px;font-weight:600}
.picker{position:relative}
.pbtn{display:flex;align-items:center;gap:8px;max-width:320px;background:#132230;border:1px solid #2a4258;border-radius:10px;padding:6px 10px 6px 12px;font-size:13px;color:#e7eef4}
.pbtn:hover{border-color:#3d6187}
.pbtn:disabled{opacity:.6;cursor:default}
.pbtn>svg:first-child{color:#7fb2f0;flex:none}
.pbtn span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-weight:500}
.pbtn .chev{color:#8ea3b5;flex:none;transition:transform .15s}
.picker.open .pbtn{border-color:#3d6187}
.picker.open .chev{transform:rotate(180deg)}
.pop{position:absolute;top:calc(100% + 6px);left:0;z-index:50;width:340px;background:#132230;border:1px solid #2a4258;border-radius:12px;box-shadow:0 12px 32px rgba(0,0,0,.45);overflow:hidden}
.pop[hidden]{display:none}
.psearch{display:flex;align-items:center;gap:8px;padding:10px 12px;border-bottom:1px solid #1f3346;color:#8ea3b5}
.psearch input{flex:1;background:transparent;border:0;outline:0;color:#e7eef4;font:inherit;font-size:13px}
.psearch input::placeholder{color:#6f8699}
.plist{overflow-y:auto;padding:4px}
.popt{display:flex;align-items:center;gap:8px;padding:7px 10px;border-radius:8px;cursor:pointer;font-size:13px;color:#c5d3df}
.popt .pn{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.popt.act{background:#1b3247;color:#e7eef4}
.popt.cur{color:#e7eef4;font-weight:600}
.popt svg{color:#6fcf97;flex:none}
.popt mark{background:none;color:#7fb2f0;font-weight:700}
.pempty{padding:14px 10px;font-size:13px;color:#6f8699}
.pcount{padding:6px 12px;border-top:1px solid #1f3346;font-size:11px;color:#6f8699}
.facts{font-size:12px;color:#7f95a8}
.spacer{flex:1}
.newchat{display:flex;align-items:center;gap:6px;padding:6px 12px;border:1px solid #2a4258;border-radius:8px;font-size:13px}
.newchat:hover{background:#132230}
.scroll{flex:1;min-height:0;overflow-y:auto}
.thread{max-width:820px;margin:0 auto;padding:28px 20px 12px;display:flex;flex-direction:column;gap:26px;min-height:100%}
.u{display:flex;justify-content:flex-end}
.u .b{max-width:75%;background:#1b3247;border-radius:18px;padding:10px 16px;line-height:1.5;white-space:pre-wrap;word-wrap:break-word}
.a{display:flex;gap:14px;align-items:flex-start}
.av{flex:none;width:28px;height:28px;border-radius:50%;background:#132230;border:1px solid #2a4258;display:flex;align-items:center;justify-content:center;color:#f2c94c;margin-top:1px}
.a .body{flex:1;min-width:0;display:flex;flex-direction:column;gap:12px}
.answer{line-height:1.65}
.err{font-size:13px;color:#f08c8c;background:#2a1418;border:1px solid #5a2630;border-radius:8px;padding:8px 10px}
.tbl{overflow-x:auto;border:1px solid #1f3346;border-radius:10px}
table{border-collapse:collapse;width:100%;font-size:13px}
th{background:#132230;color:#8ea3b5;text-align:left;font-weight:600;padding:8px 14px;white-space:nowrap;border-bottom:1px solid #1f3346}
td{padding:7px 14px;border-top:1px solid #16283a;white-space:nowrap;text-align:left}
td.n{font-variant-numeric:tabular-nums}
tbody tr:hover td{background:#10202e}
.tfoot{display:flex;align-items:center;gap:12px;font-size:12px;color:#6f8699;margin-top:-4px}
.more{color:#7fb2f0;font-size:12px;padding:0}
.more:hover{text-decoration:underline}
.muted{color:#6f8699}
.tabs{display:inline-flex;border:1px solid #2a4258;border-radius:8px;overflow:hidden}
.tabs button{padding:6px 14px;font-size:13px;color:#8ea3b5}
.tabs button.on{background:#1b3247;color:#e7eef4}
.tabs button:hover{color:#e7eef4}
.newchat:disabled{opacity:.5;cursor:default}
.thread.wide{max-width:1240px}
.savedhead{display:flex;align-items:baseline;gap:12px;flex-wrap:wrap;color:#c5d3df;font-weight:600}
.note{font-size:12px;color:#6f8699;font-weight:400}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(480px,1fr));gap:16px}
.scard{border:1px solid #1f3346;border-radius:12px;background:#0f1e2b;padding:14px;display:flex;flex-direction:column;gap:10px;min-width:0}
.scard .chart{height:280px}
.shead{display:flex;flex-direction:column;gap:3px}
.stitle{font-weight:600}
.sq{font-size:12px;color:#6f8699;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dl.icon{padding:0 8px}
.dl.done{color:#6fcf97;border-color:#2d5a44;cursor:default}
.dl:disabled{cursor:default}
.rbar{display:flex;align-items:center;gap:10px}
.rtitle{flex:1;min-width:0;font-weight:600;font-size:13px;color:#c5d3df;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.seg{display:inline-flex;border:1px solid #2a4258;border-radius:8px;overflow:hidden}
.seg button{padding:4px 12px;font-size:12px;color:#8ea3b5}
.seg button.on{background:#1b3247;color:#e7eef4}
.dl{height:28px;padding:0 10px;border:1px solid #2a4258;border-radius:8px;display:flex;align-items:center;gap:5px;font-size:12px;color:#8ea3b5}
.dl:hover,.seg button:hover{color:#e7eef4}
.chart{height:320px;border:1px solid #1f3346;border-radius:10px;padding:10px 6px 4px}
.busy{display:flex;align-items:center;gap:10px;color:#8ea3b5;line-height:28px}
.dots{display:inline-flex;gap:4px}
.dots i{width:6px;height:6px;border-radius:50%;background:#7fb2f0;animation:blink 1.2s infinite ease-in-out}
.dots i:nth-child(2){animation-delay:.2s}
.dots i:nth-child(3){animation-delay:.4s}
@keyframes blink{0%,80%,100%{opacity:.25}40%{opacity:1}}
.empty{margin:auto 0;text-align:center;padding:20px 0}
.empty h2{font-size:26px;font-weight:600;margin:0 0 8px}
.empty p{color:#8ea3b5;margin:0 0 26px}
.cards{display:grid;grid-template-columns:1fr 1fr;gap:10px;text-align:left}
.card{display:flex;flex-direction:column;align-items:flex-start;text-align:left;gap:4px;padding:12px 14px;border:1px solid #1f3346;border-radius:12px;background:#0f1e2b}
.card:hover{background:#132230;border-color:#2a4258}
.card b{font-size:13px;font-weight:600}
.card span{font-size:13px;color:#8ea3b5}
.dock{flex:none;padding:6px 20px 12px}
.composer{max-width:820px;margin:0 auto;display:flex;align-items:flex-end;gap:8px;background:#132230;border:1px solid #2a4258;border-radius:26px;padding:8px 8px 8px 20px;cursor:text}
.composer:focus-within{border-color:#3d6187}
.composer textarea{flex:1;background:transparent;border:0;outline:0;resize:none;color:#e7eef4;font:inherit;font-size:15px;line-height:22px;padding:7px 0;max-height:200px}
.composer textarea::placeholder{color:#6f8699}
.send{flex:none;width:36px;height:36px;border-radius:50%;background:#e7eef4;color:#0d1822;display:flex;align-items:center;justify-content:center}
.send:disabled{background:#2a4258;color:#6f8699;cursor:default}
.hint{max-width:820px;margin:8px auto 0;text-align:center;font-size:11px;color:#6f8699}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{background:#2a4258;border-radius:6px}
@media (max-width:640px){.cards{grid-template-columns:1fr}.facts{display:none}.grid{grid-template-columns:1fr}}
.dupnote{margin:0 0 8px;font-size:12px;color:#e5b562}

srcDoc.js:
// Ask UBM chat, laid out like ChatGPT: one scrolling thread in a centred
// column, and the composer pinned under it, plus a Saved tab of the charts the
// user kept. Everything shown comes from the model (the page store); the
// widget only sends events out: onAsk, onPickCustomer, onClear, onDownload,
// onSaveAnswer, onOpenSaved, onRemoveSaved, onOpenInStudio. Charts are drawn with ECharts
// (loaded in the html) from the result rows; the AI only names the columns.
var SUGGEST = [
  ["Cost by month", "Show my total cost by month for the last 12 months"],
  ["Top electric users", "Find my top 5 locations by electric usage last year"],
  ["Late bills", "Which of my accounts have late bills?"],
  ["Bill errors", "Which accounts or vendors have the most bill errors?"]
];
var ROWS_COLLAPSED = 10;
// Answer mark: a lightning bolt for an energy app, not any AI vendor's logo.
var MARK = '<div class="av"><svg viewBox="0 0 24 24" width="15" height="15"><path d="M13 2 4.5 13.5H11L10 22l8.5-11.5H12L13 2z" fill="currentColor"/></svg></div>';
var DL_ICON = '<svg viewBox="0 0 24 24" width="14" height="14"><path d="M12 4v11M7 10l5 5 5-5M5 20h14" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" fill="none"/></svg>';
var SAVE_ICON = '<svg viewBox="0 0 24 24" width="14" height="14"><path d="M6 3h12v18l-6-4-6 4V3z" stroke="currentColor" stroke-width="2" stroke-linejoin="round" fill="none"/></svg>';
var SAVED_ICON = '<svg viewBox="0 0 24 24" width="14" height="14"><path d="M6 3h12v18l-6-4-6 4V3z" fill="currentColor"/></svg>';
var STUDIO_ICON = '<svg viewBox="0 0 24 24" width="14" height="14"><path d="M14 4h6v6M20 4l-9 9M18 14v5a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h5" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" fill="none"/></svg>';
var TRASH_ICON = '<svg viewBox="0 0 24 24" width="14" height="14"><path d="M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" fill="none"/></svg>';
var COLORS = ["#4c9aff", "#f2c94c", "#6fcf97", "#bb6bd9", "#f2994a", "#56ccf2", "#eb5757", "#a0b4c8"];

var M = {};
var tab = "chat";   // "chat" or "saved"
// Results on screen are keyed: "m<index>" for a chat answer, "s<id>" for a
// saved chart. Each key maps to { chart, rows, columns, rowCount, name }.
var items = {};
var expanded = {};
var view = {};      // per result: "chart" or "table"
var charts = {};    // live ECharts instances by key
var animated = {};  // results whose chart has already animated in
var lastCount = -1;

var root = document.getElementById("root");
root.innerHTML =
  '<div class="app">' +
  '<div class="top"><span class="title">Ask UBM</span>' +
  // Customer picker: a searchable list drawn inside the widget. A native
  // <select> opens an OS menu that spills outside the chat.
  '<div class="picker" id="picker"><button class="pbtn" id="pbtn" title="Customer">' +
  '<svg viewBox="0 0 24 24" width="15" height="15"><path d="M4 21V8l8-5 8 5v13M9 21v-6h6v6" stroke="currentColor" stroke-width="2" stroke-linejoin="round" fill="none"/></svg>' +
  '<span id="pname">Loading…</span>' +
  '<svg class="chev" viewBox="0 0 24 24" width="14" height="14"><path d="M6 9l6 6 6-6" stroke="currentColor" stroke-width="2" stroke-linecap="round" fill="none"/></svg></button>' +
  '<div class="pop" id="pop" hidden><div class="psearch">' +
  '<svg viewBox="0 0 24 24" width="15" height="15"><circle cx="11" cy="11" r="7" stroke="currentColor" stroke-width="2" fill="none"/><path d="M20 20l-4-4" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>' +
  '<input id="pq" placeholder="Search customers" autocomplete="off"></div>' +
  '<div class="plist" id="plist"></div><div class="pcount" id="pcount"></div></div></div>' +
  '<span class="facts" id="facts"></span><span class="spacer"></span>' +
  '<span class="tabs" id="tabs"><button data-t="chat">Chat</button><button data-t="saved">Saved</button></span>' +
  '<button class="newchat" id="clear" title="Start a new chat">' +
  '<svg viewBox="0 0 24 24" width="16" height="16"><path d="M12 5v14M5 12h14" stroke="currentColor" stroke-width="2" stroke-linecap="round" fill="none"/></svg>New chat</button>' +
  '<button class="newchat" id="refresh" title="Reload every saved chart with the latest data">' +
  '<svg viewBox="0 0 24 24" width="15" height="15"><path d="M20 11a8 8 0 1 0-2.3 5.7M20 4v7h-7" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" fill="none"/></svg>Refresh</button></div>' +
  '<div class="scroll" id="scroll"><div class="thread" id="thread"></div></div>' +
  '<div class="dock" id="dock"><div class="composer" id="composer">' +
  '<textarea id="q" rows="1" placeholder="Ask about my usage, costs, bill charges, late bills and bill errors"></textarea>' +
  '<button class="send" id="send" title="Send" disabled>' +
  '<svg viewBox="0 0 24 24" width="18" height="18"><path d="M12 19V5M5 12l7-7 7 7" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" fill="none"/></svg></button>' +
  '</div><div class="hint">Answers are based on my usage, billing, late-bill and bill-error data.</div></div>' +
  '</div>';

var $ = function (id) { return document.getElementById(id); };

function esc(s) {
  return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
    return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
  });
}

function isNum(v) {
  return typeof v === "number" || (typeof v === "string" && /^-?\d+(\.\d+)?$/.test(v) && v.length < 16);
}

// Account, meter and bill numbers, ids, codes and years are labels, not
// quantities: show them as they are, without thousands separators.
// (Plurals such as late_accounts are counts and keep their formatting.)
function isIdCol(c) {
  return /(^|_)(id|ref|account|meter|number|no|code|zip|postcode|said|year)$/i.test(String(c));
}

function fmt(v, col) {
  if (v == null || v === "") return '<span class="muted">—</span>';
  if (isNum(v) && col != null && isIdCol(col)) return esc(v);
  // Midnight timestamps are dates: 2026-04-16T00:00:00Z shows as 2026-04-16.
  if (typeof v === "string" && /^\d{4}-\d{2}-\d{2}T00:00:00(\.0+)?(Z|[+-]00(:?00)?)?$/.test(v)) return esc(v.slice(0, 10));
  if (isNum(v)) return Number(v).toLocaleString(undefined, { maximumFractionDigits: 2 });
  if (typeof v === "object") return esc(JSON.stringify(v));
  return esc(v);
}

function label(c) {
  var s = String(c).replace(/_/g, " ");
  return s.charAt(0).toUpperCase() + s.slice(1);
}

function slug(t) {
  return String(t || "").replace(/[^\w\- ]+/g, "").trim().replace(/\s+/g, "-").toLowerCase().slice(0, 60) || "ask-ubm";
}

function sameCust(a, b) { return String(a) === String(b); }

// ---- one result: table, chart and their toolbar ------------------------------

function table(it, key) {
  if (!it.columns || !it.columns.length) return "";
  var all = it.rows || [];
  var open = !!expanded[key];
  var shown = open ? all : all.slice(0, ROWS_COLLAPSED);
  var h = '<div class="tbl"><table><thead><tr>' +
    it.columns.map(function (c) { return "<th>" + esc(label(c)) + "</th>"; }).join("") + "</tr></thead><tbody>";
  shown.forEach(function (r) {
    h += "<tr>" + it.columns.map(function (c) {
      return '<td class="' + (isNum(r[c]) && !isIdCol(c) ? "n" : "") + '">' + fmt(r[c], c) + "</td>";
    }).join("") + "</tr>";
  });
  h += "</tbody></table></div>";
  var n = it.rowCount == null ? all.length : it.rowCount;
  var foot = '<div class="tfoot"><span>' + n + (n === 1 ? " row" : " rows") +
    (n > all.length ? " (first " + all.length + " kept)" : "") + "</span>";
  if (all.length > ROWS_COLLAPSED) {
    foot += '<button class="more" data-key="' + key + '">' + (open ? "Show fewer" : "Show all " + all.length + " rows") + "</button>";
  }
  return h + foot + "</div>";
}

// A label that sits on more than one row (vendor totals next to account rows,
// say) has no single value to draw: the last row or the sum would both be
// wrong somewhere. Such results, including charts saved before this check,
// are shown as a table.
function repeatedLabel(it) {
  var c = it.chart, seen = {};
  if (!c) return "";
  var rows = it.rows || [];
  for (var i = 0; i < rows.length; i++) {
    var k = shortLabel(rows[i][c.x]) + "\u0000" + (c.series ? String(rows[i][c.series]) : "");
    if (seen[k]) return shortLabel(rows[i][c.x]);
    seen[k] = 1;
  }
  return "";
}

function canChart(it) {
  return !!(it.chart && typeof echarts !== "undefined" && (it.rows || []).length > 1 && !repeatedLabel(it));
}

// extra: more toolbar buttons (Save on chat answers, Remove on saved charts)
function result(it, key, extra, showTitle) {
  if (!it.columns || !it.columns.length) return "";
  items[key] = it;
  var chart = canChart(it);
  var v = chart ? (view[key] || "chart") : "table";
  var bar = '<div class="rbar"><span class="rtitle">' + esc(showTitle && chart ? it.chart.title || "" : "") + "</span>" +
    (chart ? '<span class="seg"><button class="' + (v === "chart" ? "on" : "") + '" data-v="chart" data-key="' + key + '">Chart</button>' +
      '<button class="' + (v === "table" ? "on" : "") + '" data-v="table" data-key="' + key + '">Table</button></span>' : "") +
    (v === "chart" ? '<button class="dl" data-k="png" data-key="' + key + '" title="Download chart as PNG">' + DL_ICON + "PNG</button>" : "") +
    '<button class="dl" data-k="csv" data-key="' + key + '" title="Download the data as CSV">' + DL_ICON + "CSV</button>" +
    '<button class="dl" data-studio="' + key + '" title="Open in AG Studio to restyle it, combine it with other charts and save it as a report">' + STUDIO_ICON + "AG Studio</button>" +
    (extra || "") + "</div>";
  var dup = !chart && it.chart ? repeatedLabel(it) : "";
  var dupNote = dup ? '<div class="dupnote">Shown as a table: "' + esc(dup) + '" is on more than one row (the result mixes groupings), so a chart would show a wrong value.</div>' : "";
  return bar + dupNote + (v === "chart" ? '<div class="chart" data-key="' + key + '"></div>' : table(it, key));
}

// Chart labels: a first-of-month date reads as its month (2025-03); any
// other date keeps its day, so different invoice days stay apart.
function shortLabel(v) {
  var s = v == null ? "" : String(v);
  if (!/^\d{4}-\d{2}-\d{2}/.test(s)) return s;
  return s.slice(8, 10) === "01" ? s.slice(0, 7) : s.slice(0, 10);
}

var MAX_BARS = 30;

function chartOption(it, animate) {
  var c = it.chart, rows = it.rows || [];
  var cats = [], seen = {};
  rows.forEach(function (r) {
    var k = shortLabel(r[c.x]);
    if (!seen[k]) { seen[k] = 1; cats.push(k); }
  });
  // More bars than this cannot be read; the table and CSV keep them all.
  var allCats = cats.length;
  if (c.type === "bar" && allCats > MAX_BARS) cats = cats.slice(0, MAX_BARS);
  var series = [];
  if (c.series) {
    var groups = {}, order = [];
    rows.forEach(function (r) {
      var g = r[c.series] == null ? "—" : String(r[c.series]);
      if (!groups[g]) { groups[g] = {}; order.push(g); }
      groups[g][shortLabel(r[c.x])] = r[c.y[0]];
    });
    order.forEach(function (g) {
      series.push({ name: g, data: cats.map(function (k) { return groups[g][k] == null ? null : Number(groups[g][k]); }) });
    });
  } else {
    c.y.forEach(function (col) {
      var byCat = {};
      rows.forEach(function (r) { byCat[shortLabel(r[c.x])] = r[col]; });
      series.push({ name: label(col), data: cats.map(function (k) { return byCat[k] == null ? null : Number(byCat[k]); }) });
    });
  }
  series.forEach(function (s) {
    s.type = c.type;
    if (c.type === "bar") { s.barMaxWidth = 42; s.itemStyle = { borderRadius: [4, 4, 0, 0] }; }
    else { s.smooth = true; s.symbolSize = 6; s.connectNulls = false; }
  });
  var num = function (v) { return v == null ? "—" : Number(v).toLocaleString(undefined, { maximumFractionDigits: 2 }); };
  var many = cats.length > 8;
  return {
    animation: !!animate,
    color: COLORS,
    backgroundColor: "transparent",
    textStyle: { color: "#8ea3b5", fontFamily: "inherit" },
    grid: { left: 12, right: 18, top: series.length > 1 ? 40 : 24, bottom: 8, containLabel: true },
    legend: series.length > 1 ? { top: 0, textStyle: { color: "#c5d3df" }, icon: "roundRect", itemWidth: 12, itemHeight: 8 } : undefined,
    title: cats.length < allCats ? { text: "First " + cats.length + " of " + allCats + " shown · see Table or CSV for all", right: 4, top: 0,
      textStyle: { color: "#6f8699", fontSize: 11, fontWeight: "normal" } } : undefined,
    tooltip: { trigger: "axis", backgroundColor: "#132230", borderColor: "#2a4258", textStyle: { color: "#e7eef4" },
      valueFormatter: function (v) { return (c.y_label === "$" ? "$" : "") + num(v) + (c.y_label && c.y_label !== "$" ? " " + c.y_label : ""); } },
    xAxis: { type: "category", data: cats, axisLine: { lineStyle: { color: "#2a4258" } }, axisTick: { show: false },
      axisLabel: { color: "#8ea3b5", interval: 0, rotate: many ? 35 : 0, hideOverlap: true,
        formatter: function (s) { return s.length > 18 ? s.slice(0, 17) + "…" : s; } } },
    yAxis: { type: "value", name: c.y_label || "", nameTextStyle: { color: "#6f8699", align: "left" },
      splitLine: { lineStyle: { color: "#1a2c3d" } },
      axisLabel: { color: "#8ea3b5", formatter: function (v) {
        // Compact with up to one decimal (1.5K, 2.5M): whole thousands made
        // 1,500 and 1,200 both read as 1K / 2K.
        var a = Math.abs(v);
        var short = function (n, unit) { return String(Number(n.toFixed(1))) + unit; };
        var s = a >= 1e9 ? short(v / 1e9, "B") : a >= 1e6 ? short(v / 1e6, "M") : a >= 1e3 ? short(v / 1e3, "K") : String(Number(Number(v).toFixed(2)));
        return (c.y_label === "$" ? "$" : "") + s;
      } } },
    series: series
  };
}

// The view is rebuilt on every model change, so charts are recreated each
// time; only a chart's first appearance animates.
function drawCharts() {
  Object.keys(charts).forEach(function (k) { charts[k].dispose(); });
  charts = {};
  if (typeof echarts === "undefined") return;
  Array.prototype.forEach.call(document.querySelectorAll(".chart[data-key]"), function (el) {
    var key = el.getAttribute("data-key");
    var it = items[key];
    if (!it || !it.chart) return;
    var inst = echarts.init(el, null, { renderer: "canvas" });
    inst.setOption(chartOption(it, !animated[key]));
    animated[key] = true;
    charts[key] = inst;
  });
}

// ---- downloads ----------------------------------------------------------------

// The iframe cannot save files itself; the page's download() does it. It is
// given a full data: URL, which it decodes without a network request.
function save(dataUrl, fileName, fileType) {
  appsmith.triggerEvent("onDownload", { fileData: dataUrl, fileName: fileName, fileType: fileType });
}

function downloadChart(key) {
  var inst = charts[key], it = items[key];
  if (!inst || !it) return;
  save(inst.getDataURL({ type: "png", pixelRatio: 2, backgroundColor: "#0d1822" }), slug(it.name) + ".png", "image/png");
}

// Every row the query returned (up to the page's cap), with raw values, not
// the formatted ones on screen.
function downloadCsv(key) {
  var it = items[key];
  if (!it || !it.columns || !it.columns.length) return;
  var cell = function (v) {
    if (v == null) return "";
    var s = typeof v === "object" ? JSON.stringify(v) : String(v);
    if (/^\d{4}-\d{2}-\d{2}T00:00:00(\.0+)?(Z|[+-]00(:?00)?)?$/.test(s)) s = s.slice(0, 10);
    return /[",\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  };
  var lines = [it.columns.map(function (c) { return cell(label(c)); }).join(",")];
  (it.rows || []).forEach(function (r) {
    lines.push(it.columns.map(function (c) { return cell(r[c]); }).join(","));
  });
  // A byte-order mark so Excel reads the file as UTF-8.
  var csv = "﻿" + lines.join("\r\n");
  var b64 = btoa(unescape(encodeURIComponent(csv)));
  save("data:text/csv;base64," + b64, slug(it.name) + ".csv", "text/csv");
}

// ---- top bar --------------------------------------------------------------------

function custName() {
  var c = (M.customers || []).filter(function (x) { return sameCust(x.id, M.customer); })[0];
  return c ? c.name : "this customer";
}

function savedHere() {
  return (M.saved || []).filter(function (s) { return sameCust(s.cust, M.customer); });
}

// ---- customer picker ----------------------------------------------------------
var pActive = 0, pMatches = [];

function renderPicker() {
  var q = $("pq").value.trim().toLowerCase();
  var list = M.customers || [];
  pMatches = q ? list.filter(function (c) { return String(c.name).toLowerCase().indexOf(q) >= 0; }) : list;
  if (pActive >= pMatches.length) pActive = Math.max(0, pMatches.length - 1);
  var shown = pMatches.slice(0, 300);
  $("plist").innerHTML = shown.length ? shown.map(function (c, i) {
    var name = esc(c.name);
    if (q) {
      var at = String(c.name).toLowerCase().indexOf(q);
      name = esc(String(c.name).slice(0, at)) + "<mark>" + esc(String(c.name).slice(at, at + q.length)) + "</mark>" + esc(String(c.name).slice(at + q.length));
    }
    var cur = sameCust(c.id, M.customer);
    return '<div class="popt' + (i === pActive ? " act" : "") + (cur ? " cur" : "") + '" data-id="' + esc(c.id) + '" data-n="' + i + '">' +
      '<span class="pn">' + name + "</span>" +
      (cur ? '<svg viewBox="0 0 24 24" width="14" height="14"><path d="M5 12l5 5 9-10" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" fill="none"/></svg>' : "") +
      "</div>";
  }).join("") : '<div class="pempty">No customers match “' + esc($("pq").value) + '”</div>';
  $("pcount").textContent = pMatches.length > shown.length
    ? "Showing " + shown.length + " of " + pMatches.length + " · keep typing to narrow"
    : pMatches.length + (pMatches.length === 1 ? " customer" : " customers");
}

function scrollActive() {
  var el = $("plist").querySelector(".popt.act");
  if (el) el.scrollIntoView({ block: "nearest" });
}

function openPicker() {
  if ($("pbtn").disabled) return;
  $("pop").hidden = false;
  $("picker").classList.add("open");
  // The list can be no taller than the space below it in the widget.
  var room = root.getBoundingClientRect().bottom - $("pbtn").getBoundingClientRect().bottom - 120;
  $("plist").style.maxHeight = Math.max(160, Math.min(380, room)) + "px";
  $("pq").value = "";
  var list = M.customers || [];
  pActive = Math.max(0, list.findIndex(function (c) { return sameCust(c.id, M.customer); }));
  renderPicker();
  scrollActive();
  $("pq").focus();
}

function closePicker() {
  $("pop").hidden = true;
  $("picker").classList.remove("open");
}

function pickCustomer(id) {
  closePicker();
  if (id == null || sameCust(id, M.customer)) return;
  expanded = {}; view = {}; animated = {};
  $("pname").textContent = ((M.customers || []).filter(function (c) { return sameCust(c.id, id); })[0] || {}).name || "";
  appsmith.triggerEvent("onPickCustomer", { pickedCustomer: id, savedTab: tab === "saved" });
}

function renderTop() {
  var list = M.customers || [];
  $("pname").textContent = list.length ? custName() : (M.customer ? "Customer " + M.customer : "Loading…");
  // No switching customer mid-answer or while saved charts load.
  var locked = !!M.busy || !!M.savedLoading;
  $("pbtn").disabled = locked;
  if (locked) closePicker();
  else if (!$("pop").hidden) renderPicker();
  var f = M.facts || {};
  $("facts").textContent = f.first_month ? f.first_month + " – " + f.last_month + " · " + f.locations + " locations" : "";
  var n = savedHere().length;
  Array.prototype.forEach.call($("tabs").children, function (b) {
    var t = b.getAttribute("data-t");
    b.className = t === tab ? "on" : "";
    if (t === "saved") b.textContent = "Saved" + (n ? " (" + n + ")" : "");
  });
  $("clear").style.display = tab === "chat" ? "" : "none";
  $("refresh").style.display = tab === "saved" && n ? "" : "none";
  $("refresh").disabled = !!M.savedLoading;
  $("dock").style.display = tab === "chat" ? "" : "none";
}

// ---- chat -----------------------------------------------------------------------

function isSaved(m) {
  return (M.saved || []).some(function (s) { return sameCust(s.cust, M.customer) && s.sql === m.sql; });
}

function renderChat() {
  var msgs = M.messages || [];
  var h = "";
  if (!msgs.length && !M.busy) {
    var f = M.facts || {};
    h += '<div class="empty"><h2>What would you like to know?</h2>' +
      "<p>Ask about my usage, costs, bill charges, late bills and bill errors" +
      (f.utilities ? " (" + esc(f.utilities) + ")" : "") + ".</p><div class=\"cards\">" +
      SUGGEST.map(function (s) {
        return '<button class="card" data-q="' + esc(s[1]) + '"><b>' + esc(s[0]) + "</b><span>" + esc(s[1]) + "</span></button>";
      }).join("") + "</div></div>";
  }
  msgs.forEach(function (m, i) {
    if (m.role === "user") {
      h += '<div class="u"><div class="b">' + esc(m.text) + "</div></div>";
      return;
    }
    var it = { chart: m.chart, rows: m.rows, columns: m.columns, rowCount: m.rowCount,
      name: (m.chart && m.chart.title) || (msgs[i - 1] || {}).text };
    var done = isSaved(m);
    var saveBtn = m.sql ? '<button class="dl' + (done ? " done" : "") + '" data-save="' + i + '"' + (done ? " disabled" : "") +
      ' title="' + (done ? "Saved for this customer" : "Save to the Saved tab, shared with everyone who views this customer") + '">' + (done ? SAVED_ICON + "Saved" : SAVE_ICON + "Save") + "</button>" : "";
    h += '<div class="a">' + MARK + '<div class="body">' +
      '<div class="answer">' + esc(m.text).replace(/\n/g, "<br>") + "</div>" +
      (m.error ? '<div class="err">' + esc(m.error) + "</div>" : "") +
      result(it, "m" + i, saveBtn, true) + "</div></div>";
  });
  if (M.busy) {
    h += '<div class="a">' + MARK + '<div class="body"><div class="busy">' +
      '<span class="dots"><i></i><i></i><i></i></span>' + esc(M.busy) + "</div></div></div>";
  }
  return h;
}

// ---- saved charts -----------------------------------------------------------------

function renderSaved() {
  var list = savedHere();
  if (!list.length) {
    return '<div class="empty"><h2>No saved charts yet</h2><p>Use <b>Save</b> under any answer in the chat to keep it here for ' +
      esc(custName()) + ". Saved charts reload with the latest data each time you open this tab.</p>" +
      '<p class="note">Saved charts are shared with everyone who views this customer.</p></div>';
  }
  var data = M.savedData || {};
  var h = '<div class="savedhead"><span>' + list.length + " saved for " + esc(custName()) + "</span>" +
    '<span class="note">Shared with everyone who views this customer · reloaded with the latest data</span></div><div class="grid">';
  list.forEach(function (s) {
    var d = data[s.id];
    var title = (s.chart && s.chart.title) || s.question;
    var removeBtn = '<button class="dl icon" data-remove="' + esc(s.id) + '" title="Remove from Saved">' + TRASH_ICON + "</button>";
    h += '<div class="scard"><div class="shead"><div class="stitle">' + esc(title) + "</div>" +
      '<div class="sq">' + esc(s.question) + " · saved " + esc(String(s.savedAt || "").slice(0, 10)) +
      (s.savedBy ? " by " + esc(String(s.savedBy).split("@")[0]) : "") + "</div></div>";
    if (!d || d.loading) {
      h += '<div class="busy"><span class="dots"><i></i><i></i><i></i></span>Loading the latest data…</div>' +
        '<div class="rbar"><span class="rtitle"></span>' + removeBtn + "</div>";
    } else if (d.error) {
      h += '<div class="err">' + esc(d.error) + '</div><div class="rbar"><span class="rtitle"></span>' + removeBtn + "</div>";
    } else if (!d.columns || !d.columns.length) {
      h += '<div class="muted">No data for this chart any more.</div><div class="rbar"><span class="rtitle"></span>' + removeBtn + "</div>";
    } else {
      h += result({ chart: s.chart, rows: d.rows, columns: d.columns, rowCount: d.rowCount, name: title },
        "s" + s.id, removeBtn, false);
    }
    h += "</div>";
  });
  return h + "</div>";
}

// ---- render ---------------------------------------------------------------------

function renderMain() {
  items = {};
  $("thread").className = tab === "saved" ? "thread wide" : "thread";
  $("thread").innerHTML = tab === "saved" ? renderSaved() : renderChat();
  drawCharts();
  if (tab !== "chat") return;
  var count = (M.messages || []).length + (M.busy ? 0.5 : 0);
  if (count !== lastCount) {
    var sc = $("scroll");
    sc.scrollTop = sc.scrollHeight;
    lastCount = count;
  }
}

function syncSend() {
  $("send").disabled = !!M.busy || !$("q").value.trim();
}

function render(model) {
  M = model || {};
  renderTop();
  renderMain();
  syncSend();
}

function showTab(t) {
  if (t === tab) return;
  tab = t;
  lastCount = -1;
  renderTop();
  renderMain();
  $("scroll").scrollTop = tab === "chat" ? $("scroll").scrollHeight : 0;
  if (tab === "saved" && savedHere().length) appsmith.triggerEvent("onOpenSaved", {});
}

function grow() {
  var t = $("q");
  t.style.height = "auto";
  t.style.height = Math.min(t.scrollHeight, 200) + "px";
}

function send(text) {
  var q = String(text == null ? $("q").value : text).trim();
  if (!q || M.busy) return;
  $("q").value = "";
  grow();
  syncSend();
  appsmith.triggerEvent("onAsk", { question: q });
}

$("send").addEventListener("click", function () { send(); });
$("q").addEventListener("input", function () { grow(); syncSend(); });
$("q").addEventListener("keydown", function (e) {
  if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); send(); }
});
$("composer").addEventListener("click", function () { $("q").focus(); });
$("clear").addEventListener("click", function () {
  expanded = {}; view = {}; animated = {};
  appsmith.triggerEvent("onClear", {});
});
$("refresh").addEventListener("click", function () { appsmith.triggerEvent("onOpenSaved", {}); });
$("tabs").addEventListener("click", function (e) {
  var b = e.target.closest("button");
  if (b) showTab(b.getAttribute("data-t"));
});
$("pbtn").addEventListener("click", function () { if ($("pop").hidden) openPicker(); else closePicker(); });
$("pq").addEventListener("input", function () { pActive = 0; renderPicker(); $("plist").scrollTop = 0; });
$("pq").addEventListener("keydown", function (e) {
  if (e.key === "ArrowDown" || e.key === "ArrowUp") {
    e.preventDefault();
    var n = Math.min(pMatches.length, 300);
    if (!n) return;
    pActive = (pActive + (e.key === "ArrowDown" ? 1 : n - 1)) % n;
    renderPicker();
    scrollActive();
  } else if (e.key === "Enter") {
    e.preventDefault();
    if (pMatches[pActive]) pickCustomer(pMatches[pActive].id);
  } else if (e.key === "Escape") {
    closePicker();
    $("pbtn").focus();
  }
});
$("plist").addEventListener("click", function (e) {
  var o = e.target.closest(".popt");
  if (o) pickCustomer(o.getAttribute("data-id"));
});
$("plist").addEventListener("mousemove", function (e) {
  var o = e.target.closest(".popt");
  if (!o) return;
  var n = Number(o.getAttribute("data-n"));
  if (n === pActive) return;
  var prev = $("plist").querySelector(".popt.act");
  if (prev) prev.classList.remove("act");
  o.classList.add("act");
  pActive = n;
});
document.addEventListener("mousedown", function (e) {
  if (!$("pop").hidden && !e.target.closest("#picker")) closePicker();
});
$("thread").addEventListener("click", function (e) {
  var card = e.target.closest(".card");
  if (card) { send(card.getAttribute("data-q")); return; }
  var seg = e.target.closest(".seg button");
  if (seg) { view[seg.getAttribute("data-key")] = seg.getAttribute("data-v"); renderMain(); return; }
  var sv = e.target.closest("[data-save]");
  if (sv) { if (!sv.disabled) appsmith.triggerEvent("onSaveAnswer", { answerIndex: Number(sv.getAttribute("data-save")) }); return; }
  var st = e.target.closest("[data-studio]");
  if (st) { appsmith.triggerEvent("onOpenInStudio", { studioKey: st.getAttribute("data-studio") }); return; }
  var rm = e.target.closest("[data-remove]");
  if (rm) { appsmith.triggerEvent("onRemoveSaved", { savedId: rm.getAttribute("data-remove") }); return; }
  var dl = e.target.closest(".dl[data-k]");
  if (dl) {
    if (dl.getAttribute("data-k") === "csv") downloadCsv(dl.getAttribute("data-key"));
    else downloadChart(dl.getAttribute("data-key"));
    return;
  }
  var more = e.target.closest(".more");
  if (more) {
    var key = more.getAttribute("data-key");
    expanded[key] = !expanded[key];
    renderMain();
  }
});

// ---- fit to the browser window --------------------------------------------
// Appsmith sizes this widget by its content (auto height) and has no way to
// size it to the window, and the iframe cannot read the window size. An
// IntersectionObserver can still see how much of the iframe is on screen, so:
// grow tall, measure the visible part, then shrink to exactly that. The page
// then has nothing to scroll and the thread is the only scrollbar.
var MIN_H = 420, PROBE_H = 2400, FALLBACK_H = 700;
var fitted = false, lastW = window.innerWidth, fallbackTimer = null;

function setH(h) {
  root.style.height = Math.round(h) + "px";
  var sc = $("scroll");
  if (sc && tab === "chat") sc.scrollTop = sc.scrollHeight;
}

function probe() {
  fitted = false;
  setH(PROBE_H);
  clearTimeout(fallbackTimer);
  fallbackTimer = setTimeout(function () { if (!fitted) { fitted = true; setH(FALLBACK_H); } }, 4000);
}

var steps = [];
for (var s = 0; s <= 200; s++) steps.push(s / 200);
new IntersectionObserver(function (entries) {
  if (fitted) return;
  var r = entries[entries.length - 1].intersectionRect;
  // Measure only once Appsmith has grown the iframe past the visible area
  // (otherwise the clip is the iframe's own edge) and its top is on screen.
  if (r.height < 50 || r.top > 2 || window.innerHeight < r.height + 20) return;
  fitted = true;
  clearTimeout(fallbackTimer);
  setH(Math.max(MIN_H, r.height - 6));
}, { threshold: steps }).observe(root);

// A width change means the browser window was resized: fit again. (Height
// changes also come from Appsmith resizing the iframe to match, so ignore them.)
window.addEventListener("resize", function () {
  Object.keys(charts).forEach(function (k) { charts[k].resize(); });
  if (Math.abs(window.innerWidth - lastW) < 2) return;
  lastW = window.innerWidth;
  probe();
});
probe();

appsmith.onReady(function () {
  render(appsmith.model);
  appsmith.onModelChange(function (m) { render(m); });
});

