.note{font-size:12px;color:#6f8699;font-weight:400}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(480px,1fr));gap:16px}
.scard{border:1px solid #1f3346;border-radius:12px;background:#0f1e2b;padding:14px;display:flex;flex-direction:column;gap:10px;min-width:0}
.scard .chart{height:280px}
.shead{display:flex;flex-direction:column;gap:3px}
.stitle{font-weight:600}
.sq{font-size:12px;color:#6f8699;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dl.icon{padding:0 8px}
.dl.done{color:#6fcf97;border-color:#2d5a44;cursor:default}
.dl:disabled{cursor:default}
.rbar{display:flex;align-items:center;gap:10px}
.rtitle{flex:1;min-width:0;font-weight:600;font-size:13px;color:#c5d3df;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.seg{display:inline-flex;border:1px solid #2a4258;border-radius:8px;overflow:hidden}
.seg button{padding:4px 12px;font-size:12px;color:#8ea3b5}
.seg button.on{background:#1b3247;color:#e7eef4}
.dl{height:28px;padding:0 10px;border:1px solid #2a4258;border-radius:8px;display:flex;align-items:center;gap:5px;font-size:12px;color:#8ea3b5}
.dl:hover,.seg button:hover{color:#e7eef4}
.chart{height:320px;border:1px solid #1f3346;border-radius:10px;padding:10px 6px 4px}
.busy{display:flex;align-items:center;gap:10px;color:#8ea3b5;line-height:28px}
.dots{display:inline-flex;gap:4px}
.dots i{width:6px;height:6px;border-radius:50%;background:#7fb2f0;animation:blink 1.2s infinite ease-in-out}
.dots i:nth-child(2){animation-delay:.2s}
.dots i:nth-child(3){animation-delay:.4s}
@keyframes blink{0%,80%,100%{opacity:.25}40%{opacity:1}}
.empty{margin:auto 0;text-align:center;padding:20px 0}
.empty h2{font-size:26px;font-weight:600;margin:0 0 8px}
.empty p{color:#8ea3b5;margin:0 0 26px}
.cards{display:grid;grid-template-columns:1fr 1fr;gap:10px;text-align:left}
.card{display:flex;flex-direction:column;align-items:flex-start;text-align:left;gap:4px;padding:12px 14px;border:1px solid #1f3346;border-radius:12px;background:#0f1e2b}
.card:hover{background:#132230;border-color:#2a4258}
.card b{font-size:13px;font-weight:600}
.card span{font-size:13px;color:#8ea3b5}
.dock{flex:none;padding:6px 20px 12px}
.composer{max-width:820px;margin:0 auto;display:flex;align-items:flex-end;gap:8px;background:#132230;border:1px solid #2a4258;border-radius:26px;padding:8px 8px 8px 20px;cursor:text}
.composer:focus-within{border-color:#3d6187}
.composer textarea{flex:1;background:transparent;border:0;outline:0;resize:none;color:#e7eef4;font:inherit;font-size:15px;line-height:22px;padding:7px 0;max-height:200px}
.composer textarea::placeholder{color:#6f8699}
.send{flex:none;width:36px;height:36px;border-radius:50%;background:#e7eef4;color:#0d1822;display:flex;align-items:center;justify-content:center}
.send:disabled{background:#2a4258;color:#6f8699;cursor:default}
.hint{max-width:820px;margin:8px auto 0;text-align:center;font-size:11px;color:#6f8699}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{background:#2a4258;border-radius:6px}
@media (max-width:640px){.cards{grid-template-columns:1fr}.facts{display:none}.grid{grid-template-columns:1fr}}
.dupnote{margin:0 0 8px;font-size:12px;color:#e5b562}

